import prismaMock from '../prisma-mock';
import {
  deleteComment,
  favoriteArticle,
  unfavoriteArticle,
  updateComment,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(unfavoriteArticle(slug, id)).rejects.toThrowError();
    });
  });

  describe('updateComment', () => {
    const slug = 'How-to-train-your-dragon';
    const commentId = 123;
    const authorId = 456;
    const minutesAgo = (minutes: number) => new Date(Date.now() - minutes * 60 * 1000);

    const mockedUpdatedComment = {
      id: commentId,
      createdAt: minutesAgo(5),
      updatedAt: minutesAgo(5),
      editedAt: new Date(),
      body: 'edited body',
      authorId,
      author: {
        username: 'RealWorld',
        bio: null,
        image: null,
        followedBy: [],
      },
    };

    test('should throw a 422 when the body is blank', async () => {
      // Then
      await expect(updateComment('', slug, commentId, authorId)).rejects.toMatchObject({
        errorCode: 422,
        message: { errors: { body: ["can't be blank"] } },
      });
    });

    test('should throw a 404 when the comment is not found', async () => {
      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment('edited body', slug, commentId, authorId)).rejects.toMatchObject({
        errorCode: 404,
        message: { errors: { comment: ['not found'] } },
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should set editedAt when the author edits within 30 minutes', async () => {
      // Given
      const existingComment = {
        id: commentId,
        createdAt: minutesAgo(5),
        authorId,
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(existingComment);
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // Then
      const result = await updateComment('edited body', slug, commentId, authorId);

      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({
            body: 'edited body',
            editedAt: expect.any(Date),
          }),
        }),
      );
      expect(result.body).toBe('edited body');
      expect(result.editedAt).toBeInstanceOf(Date);
    });

    test('should throw an error when someone other than the author edits the comment', async () => {
      // Given
      const existingComment = {
        id: commentId,
        createdAt: minutesAgo(5),
        authorId: 999,
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(existingComment);

      // Then
      await expect(updateComment('edited body', slug, commentId, authorId)).rejects.toThrowError();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should throw an error when the comment is older than 15 minutes', async () => {
      // Given
      const existingComment = {
        id: commentId,
        createdAt: minutesAgo(16),
        authorId,
      };

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(existingComment);

      // Then
      await expect(updateComment('edited body', slug, commentId, authorId)).rejects.toThrowError();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });
});
